<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { getHistory } from '../../services/api';
const history = ref<{ id: string; platform: string; status: string; title: string | null; createdAt: string }[]>([]);
onMounted(async () => { try { history.value = await getHistory(); } catch { uni.showToast({ title: '无法加载记录', icon: 'none' }); } });
function open(id: string) { uni.navigateTo({ url: `/pages/result/index?id=${id}` }); }
</script>
<template><view class="page"><text class="headline">提取记录</text><view class="filters"><text class="selected">全部</text><text>视频</text><text>图片</text></view><view v-if="history.length" class="list"><view v-for="item in history" :key="item.id" class="record" @click="open(item.id)"><view class="thumb">▶</view><view><b>{{ item.title || item.platform }}</b><text>{{ item.platform }} · {{ item.status }} · {{ new Date(item.createdAt).toLocaleDateString() }}</text></view></view></view><view v-else class="empty"><text>⌁</text><b>暂无记录</b><span>成功提取后会在这里保留 30 天</span></view></view></template>
<style scoped>.page{padding:42rpx 36rpx;min-height:100vh;background:#f7f8fb}.headline{font-size:46rpx;font-family:serif;font-weight:800}.filters{display:flex;gap:18rpx;margin-top:32rpx}.filters text{background:#ebe8f1;padding:12rpx 26rpx;border-radius:99rpx;color:#777080;font-size:24rpx}.filters .selected{background:#6f3ff5;color:#fff}.list{margin-top:28rpx}.record{display:flex;gap:20rpx;align-items:center;padding:24rpx;background:#fff;border-radius:22rpx;margin-bottom:16rpx}.thumb{width:76rpx;height:76rpx;display:grid;place-items:center;background:#ede7ff;color:#6f3ff5;border-radius:18rpx}.record view:last-child{display:flex;flex-direction:column;gap:8rpx}.record b{font-size:27rpx}.record text{font-size:21rpx;color:#827c8d}.empty{height:500rpx;display:flex;flex-direction:column;justify-content:center;align-items:center;color:#827c8d;gap:12rpx}.empty text{font-size:70rpx;color:#b49eff}.empty b{font-size:30rpx;color:#4b4654}.empty span{font-size:23rpx}</style>
